insert into public.services (id,slug,name,tagline,description,image,price,active,sort_order) values
('ca5a0000-0000-4000-8000-000000000501','dubinsko-pranje-duseka-sofa-i-fotelja','Dubinsko pranje dušeka, sofa i fotelja','Svežina omiljenog mesta za odmor.','Dubinski peremo dušeke, sofe i fotelje u Beogradu. Materijal, dimenzije, broj sedećih mesta, stanje i način čišćenja potvrđujemo pre dolaska, uz dogovor o sušenju i korišćenju nakon pranja.','/images/services/dubinsko-pranje-duseka-sofa-i-fotelja.webp',240000,true,64),
('ca5a0000-0000-4000-8000-000000000502','skidanje-i-postavljanje-tapeta','Skidanje i postavljanje tapeta','Novi zidovi, sa pažnjom prema svakom spoju.','Skidamo stare i postavljamo nove tapete u Beogradu. Površinu zidova, stanje podloge, vrstu tapeta, pripremu i završne detalje dogovaramo pre rada, uz zaštitu prostora i sređivanje nakon završetka.','/images/services/skidanje-i-postavljanje-tapeta.webp',null,true,65),
('ca5a0000-0000-4000-8000-000000000503','praznjenje-podruma-tavana-i-garaza','Pražnjenje podruma, tavana i garaža','Oslobodite prostor za ono što vam je važno.','Praznimo podrume, tavane i garaže u Beogradu. Unapred dogovaramo šta ostaje, šta iznosimo, količinu stvari, pristup i odvoz, uz jasnu ponudu za rad i odgovarajuće zbrinjavanje.','/images/services/praznjenje-podruma-tavana-i-garaza.webp',null,true,66),
('ca5a0000-0000-4000-8000-000000000504','kosenje-trave-i-sisanje-zive-ograde','Košenje trave i šišanje žive ograde','Uredna bašta, više vremena za uživanje.','Kosimo travu i šišamo živu ogradu u Beogradu. Površinu travnjaka, visinu i dužinu ograde, pristup, opremu i uklanjanje zelenog otpada dogovaramo za jednu posetu ili redovno održavanje.','/images/services/kosenje-trave-i-sisanje-zive-ograde.webp',null,true,67),
('ca5a0000-0000-4000-8000-000000000505','ciscenje-i-odrzavanje-bazena','Čišćenje i održavanje bazena','Vi uživate u vodi. Mi brinemo o detaljima.','Čistimo i održavamo privatne bazene u Beogradu. Čišćenje površine, dna i ivica, pregled dostupne filtracije i redovno održavanje dogovaramo prema dimenzijama, stanju vode i opremi.','/images/services/ciscenje-i-odrzavanje-bazena.webp',null,true,68)
